//! The malicious corpus (`tests/fixtures/xlsx/malicious/`, generated by
//! `tests/fixtures/xlsx/gen_fixtures.py`) plus inputs generated here (20,000
//! real zip entries, budget overruns). Every input must be rejected (or
//! safely opened) quickly, without unbounded allocation. The limits are the
//! same as tally-io-ods.

#![allow(clippy::unwrap_used)] // tests may unwrap (docs/contributing.md)

mod common;

use std::io::{Cursor, Write};
use std::time::{Duration, Instant};

use common::read_fixture;
use tally_io_xlsx::{read_xlsx, Limits, XlsxError};
use tally_model::WorkbookData;
use tally_types::Value;

fn read_bytes(
    name: &str,
    bytes: Vec<u8>,
    limits: &Limits,
) -> (Result<WorkbookData, XlsxError>, Duration) {
    let t = Instant::now();
    let r = read_xlsx(Cursor::new(bytes), limits);
    let t = t.elapsed();
    eprintln!(
        "TIMING {name}: {t:?} -> {}",
        match &r {
            Ok(_) => "Ok".to_string(),
            Err(e) => e.to_string(),
        }
    );
    (r, t)
}

fn read_with(rel: &str, limits: &Limits) -> (Result<WorkbookData, XlsxError>, Duration) {
    read_bytes(rel, read_fixture(rel), limits)
}

fn read(rel: &str) -> (Result<WorkbookData, XlsxError>, Duration) {
    read_with(rel, &Limits::default())
}

fn limit_what(r: &Result<WorkbookData, XlsxError>) -> &'static str {
    match r {
        Err(XlsxError::LimitExceeded { what, .. }) => what,
        other => panic!("expected LimitExceeded, got {other:?}"),
    }
}

/// A minimal valid package with the given worksheet / shared strings XML.
fn package(sheet: &str, sst: Option<&str>) -> Vec<u8> {
    let mut z = zip::ZipWriter::new(Cursor::new(Vec::new()));
    let opts = zip::write::SimpleFileOptions::default();
    let rels = concat!(
        r#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">"#,
        r#"<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>"#,
        r#"<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings" Target="sharedStrings.xml"/>"#,
        "</Relationships>"
    );
    let wb = concat!(
        r#"<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" "#,
        r#"xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">"#,
        r#"<sheets><sheet name="S" sheetId="1" r:id="rId1"/></sheets></workbook>"#
    );
    let mut entries = vec![
        ("xl/workbook.xml", wb.to_string()),
        ("xl/_rels/workbook.xml.rels", rels.to_string()),
        ("xl/worksheets/sheet1.xml", sheet.to_string()),
    ];
    if let Some(s) = sst {
        entries.push(("xl/sharedStrings.xml", s.to_string()));
    }
    for (name, data) in entries {
        z.start_file(name, opts).unwrap();
        z.write_all(data.as_bytes()).unwrap();
    }
    z.finish().unwrap().into_inner()
}

const WS: &str =
    r#"<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>"#;
const WS_END: &str = "</sheetData></worksheet>";

#[test]
fn zip_bomb_is_rejected_within_one_second() {
    // 160 MiB of whitespace deflated ~1000:1. The ratio guard trips after
    // ~10 MiB of output; the inflated size is never allocated.
    let (r, t) = read("malicious/zip-bomb.xlsx");
    assert_eq!(limit_what(&r), "compression ratio");
    assert!(t < Duration::from_secs(1), "took {t:?}");
}

#[test]
fn zip_bomb_hits_entry_cap_when_ratio_is_disabled() {
    let limits = Limits {
        max_ratio: u32::MAX,
        max_sheet_xml_bytes: 8 * 1024 * 1024,
        ..Limits::default()
    };
    let (r, t) = read_with("malicious/zip-bomb.xlsx", &limits);
    assert_eq!(limit_what(&r), "zip entry uncompressed bytes");
    assert!(t < Duration::from_secs(1), "took {t:?}");
}

#[test]
fn total_bytes_cap() {
    let limits = Limits {
        max_total_bytes: 1024,
        ..Limits::default()
    };
    let (r, _) = read_with("excel365-basic.xlsx", &limits);
    assert_eq!(limit_what(&r), "total uncompressed bytes");
}

#[test]
fn doctype_is_forbidden_in_every_part() {
    for f in [
        "malicious/doctype-xxe.xlsx",
        "malicious/billion-laughs.xlsx",
        "malicious/doctype-in-styles.xlsx",
        "malicious/doctype-in-workbook.xlsx",
    ] {
        let (r, t) = read(f);
        assert!(matches!(r, Err(XlsxError::ForbiddenDoctype)), "{f}: {r:?}");
        assert!(t < Duration::from_secs(1), "{f} took {t:?}");
    }
}

